import 'package:ecommerce_admin_pannal/features/banner/domain/entities/banner_entity.dart';import 'package:ecommerce_admin_pannal/features/brand/domain/entities/brand_entity.dart';import 'package:ecommerce_admin_pannal/features/brand/presentation/screens/all_brands/brands.dart';import 'package:ecommerce_admin_pannal/features/categories/data/models/category_model.dart';import 'package:ecommerce_admin_pannal/features/categories/domain/entities/category_entity.dart';import 'package:ecommerce_admin_pannal/features/media/presentation/screens/media.dart';import 'package:ecommerce_admin_pannal/features/order/domain/entities/order_entity.dart';import 'package:ecommerce_admin_pannal/features/product/domain/entities/product_entity.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:go_router/go_router.dart';import 'package:flutter/material.dart';import '../common/widgets/layouts/templates/site_layout.dart';import '../common/widgets/success_screen/success_screen.dart';import '../features/auth/presentation/cubit/verify_email_cubit/verify_email_cubit.dart';import '../features/auth/presentation/screens/forget_password/forget_password.dart';import '../features/auth/presentation/screens/login/login_screen.dart';import '../features/auth/presentation/screens/reset_password/reset_password.dart';import '../features/auth/presentation/screens/signup/verify_email.dart';import '../features/banner/data/models/banner_model.dart';import '../features/banner/presentation/screens/all_banners/banners.dart';import '../features/banner/presentation/screens/create_banner/create_banner.dart';import '../features/banner/presentation/screens/edit_banner/edit_banner.dart';import '../features/brand/data/models/brand_model.dart';import '../features/brand/presentation/screens/create_brand/create_brand.dart';import '../features/brand/presentation/screens/edit_brand/edit_brand.dart';import '../features/categories/presentation/controller/category/category_cubit.dart';import '../features/categories/presentation/screens/all_categories/categories.dart';import '../features/categories/presentation/screens/create_category/create_category.dart';import '../features/categories/presentation/screens/edit_category/edit_category.dart';import '../features/customer/presentation/screens/all_customers/customers.dart';import '../features/customer/presentation/screens/customer_detail/customer_detail.dart';import '../features/dashboard/presentation/screens/dashboard.dart';import '../features/order/domain/entities/user_entity.dart';import '../features/order/presentation/screens/all_orders/orders.dart';import '../features/order/presentation/screens/order_detail/order_detail.dart';import '../features/product/data/models/product_model.dart';import '../features/product/presentation/screens/all_products/products.dart';import '../features/product/presentation/screens/create_product/create_product.dart';import '../features/product/presentation/screens/edit_product/edit_product.dart';import '../features/profile/presentation/screens/profile.dart';import '../features/settings/presentation/screens/settings.dart';import 'auth_refresh.dart';final authRefreshNotifier = AuthRefreshNotifier();const _publicPaths = <String>[  '/login',  '/forget',  '/reset',  '/verify-email',];final GoRouter appRouter = GoRouter(  initialLocation: '/login',  refreshListenable: authRefreshNotifier,  redirect: (context, state) {    final isLoggedIn = authRefreshNotifier.isLoggedIn;    final isEmailVerified = authRefreshNotifier.isEmailVerified;    final isPublicPath = _publicPaths.contains(state.matchedLocation);    if (!isLoggedIn) {      if (isPublicPath) return null;      return '/login';    }    if (!isEmailVerified) {      if (state.matchedLocation == '/verify-email') return null;      return '/verify-email';    }    if (isPublicPath) {      return '/dashboard';    }    return null;  },  routes: [    // =========================================================    // شاشات المصادقة العامة    // =========================================================    GoRoute(      name: 'login',      path: '/login',      builder: (context, state) => const LoginScreen(),    ),    GoRoute(      name: 'forget',      path: '/forget',      builder: (context, state) => const ForgetPasswordScreen(),    ),    GoRoute(      name: 'reset',      path: '/reset',      builder: (context, state) {        final email = state.uri.queryParameters['email'] ?? '';        return ResetPasswordScreen(email: email);      },    ),    GoRoute(      name: 'verify-email',      path: '/verify-email',      builder: (context, state) {        final email = state.uri.queryParameters['email'] ?? '';        return VerifyEmailScreen(email: email);      },    ),    // =========================================================    // لوحة التحكم والهيكل الأساسي للموقع (الروابط الأساسية فقط)    // =========================================================    StatefulShellRoute.indexedStack(      builder: (context, state, navigationShell) {        return SiteTemplate(          useLayout: false,          desktop: navigationShell,          tablet: navigationShell,          mobile: navigationShell,        );      },      branches: [        // 1. فرع الداشبورد        StatefulShellBranch(          routes: [            GoRoute(              name: 'dashboard',              path: '/dashboard',              builder: (context, state) => const DashboardScreen(),            ),          ],        ),        // 2. فرع الأقسام        StatefulShellBranch(          routes: [            GoRoute(              name: 'categories',              path: '/categories',              builder: (context, state) => const CategoriesScreen(),            ),          ],        ),        StatefulShellBranch(          routes: [            GoRoute(              name: 'brands',              path: '/brands',              builder: (context, state) => const BrandsScreen(),            ),          ],        ),        StatefulShellBranch(          routes: [            GoRoute(              name: 'banners',              path: '/banners',              builder: (context, state) => const BannersScreen(),            ),          ],        ),        StatefulShellBranch(          routes: [            GoRoute(              name: 'products',              path: '/products',              builder: (context, state) => const ProductsScreen(),            ),          ],        ),        StatefulShellBranch(          routes: [            GoRoute(              name: 'settings',              path: '/settings',              builder: (context, state) => const SettingsScreen(),            ),          ],        ),        StatefulShellBranch(          routes: [            GoRoute(              name: 'profile',              path: '/profile',              builder: (context, state) => const ProfileScreen(),            ),          ],        ),        // StatefulShellBranch(        //   routes: [        //     GoRoute(        //       name: 'logout',        //       path: '/logout',        //       builder: (context, state) => const logoutScreen(),        //     ),        //   ],        // ),        StatefulShellBranch(          routes: [            GoRoute(              name: 'customers',              path: '/customers',              builder: (context, state) => const CustomersScreen(),            ),          ],        ),        StatefulShellBranch(          routes: [            GoRoute(              name: 'orders',              path: '/orders',              builder: (context, state) => const OrdersScreen(),            ),          ],        ),        // 3. فرع الميديا        StatefulShellBranch(          routes: [            GoRoute(              name: 'media',              path: '/media',              builder: (context, state) => const MediaScreen(),            ),          ],        ),      ],    ),    // =========================================================    // المسارات الفرعية (خارج الـ IndexedStack والـ Shell)    // =========================================================    GoRoute(      path: '/categories/create-category',      builder: (context, state) {        return const CreateCategoryScreen();      },    ),    GoRoute(      path: '/categories/edit-category',      builder: (context, state) {        final categoryEntity = state.extra as CategoryEntity;        return EditCategoryScreen(category: categoryEntity);      },    )    ,        GoRoute(      name: 'create-brand',      path: '/brands/create-brand',      builder: (context, state) => const CreateBrandScreen(),    ),    GoRoute(      name: 'edit-brand',      path: '/brands/edit-brand',      builder: (context, state) {        final brand = state.extra as BrandEntity;        return EditBrandScreen(brand: brand);      },    ),    GoRoute(      name: 'customer-detail',      path: '/customers/customer-detail',      builder: (context, state) {        final UserEntity user = state.extra as UserEntity;        return CustomerDetailScreen(user: user);      },    ),    GoRoute(      name: 'order-detail',      path: '/orders/order-detail',      builder: (context, state) {        final OrderEntity order = state.extra as OrderEntity;        return OrderDetailScreen(order: order);      },    ),    GoRoute(      name: 'create-banner',      path: '/banners/create-banner',      builder: (context, state) => const CreateBannerScreen(),    ),    GoRoute(      name: 'edit-banner',      path: '/banners/edit-banner',      builder: (context, state) {        final BannerEntity banner = state.extra as BannerEntity;        return EditBannerScreen(banner: banner);      },    ),    GoRoute(      name: 'create-product',      path: '/products/create-product',      builder: (context, state) => const CreateProductScreen(),    ),    GoRoute(      name: 'edit-product',      path: '/products/edit-product',      builder: (context, state) {        final ProductEntity product = state.extra as ProductEntity;        return EditProductScreen(product: product);      },    ),    // =========================================================    // SUCCESS SCREEN    // =========================================================    GoRoute(      name: 'success-screen',      path: '/success-screen',      builder: (context, state) {        final image = state.uri.queryParameters['image'] ?? '';        final title = state.uri.queryParameters['title'] ?? '';        final subTitle = state.uri.queryParameters['subTitle'] ?? '';        final controller = state.extra as VerifyEmailCubit;        return SuccessScreen(          image: image,          title: title,          subTitle: subTitle,          controller: controller,        );      },    ),  ],);